// Local dev shim (see note below). Re-exports the globally-installed Playwright so that
// "import { chromium } from "playwright"" resolves in a sandbox where npm install is blocked.
// In a normal environment, "npm install" provides the real package and this is not used.

import pw from "/opt/homebrew/bin/node_modules/playwright/index.js";

export const chromium = pw.chromium;
export const firefox = pw.firefox;
export const webkit = pw.webkit;
export const devices = pw.devices;
export const request = pw.request;
export const selectors = pw.selectors;
export const errors = pw.errors;

export default pw;